function UnitsText($units){if($null -eq $units){return $null};return [string]::new([char[]]([int[]]$units))}
$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('DecimalParseProvider'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$builder=$assembly.DefineDynamicModule('Main').DefineType('ParseProvider',[Reflection.TypeAttributes]'Public,Sealed');$builder.AddInterfaceImplementation([IFormatProvider]);$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public)|Out-Null;$fields=@{};foreach($spec in @(@('Calls',[int]),@('LastType',[type]),@('Result',[object]),@('Error',[Exception]))){$fields[$spec[0]]=$builder.DefineField($spec[0],$spec[1],[Reflection.FieldAttributes]::Public)};$method=$builder.DefineMethod('GetFormat',[Reflection.MethodAttributes]'Public,Virtual,Final,HideBySig,NewSlot',[object],[type[]]@([type]));$il=$method.GetILGenerator();$op=[Reflection.Emit.OpCodes];$il.Emit($op::Ldarg_0);$il.Emit($op::Dup);$il.Emit($op::Ldfld,$fields.Calls);$il.Emit($op::Ldc_I4_1);$il.Emit($op::Add);$il.Emit($op::Stfld,$fields.Calls);$il.Emit($op::Ldarg_0);$il.Emit($op::Ldarg_1);$il.Emit($op::Stfld,$fields.LastType);$result=$il.DefineLabel();$il.Emit($op::Ldarg_0);$il.Emit($op::Ldfld,$fields.Error);$il.Emit($op::Brfalse,$result);$il.Emit($op::Ldarg_0);$il.Emit($op::Ldfld,$fields.Error);$il.Emit($op::Throw);$il.MarkLabel($result);$il.Emit($op::Ldarg_0);$il.Emit($op::Ldfld,$fields.Result);$il.Emit($op::Ret);$builder.DefineMethodOverride($method,[IFormatProvider].GetMethod('GetFormat'));$providerType=$builder.CreateType();$delegates=@{};$span=[ReadOnlySpan``1].MakeGenericType([char]);foreach($name in $plan.types){$native=[type]::GetType($name,$true);foreach($route in @('string','chars')){foreach($trying in @($false,$true)){$inputType=[string];if($route -eq 'chars'){$inputType=$span};$types=[type[]]@($inputType,[Globalization.NumberStyles],[IFormatProvider]);if($trying){$types=[type[]]@($inputType,[Globalization.NumberStyles],[IFormatProvider],$native.MakeByRefType())};$method=$native.GetMethod($(if($trying){'TryParse'}else{'Parse