$rows=[Collections.Generic.List[object]]::new();foreach($name in $plan.types){$native=[type]::GetType($name,$true);for($profileIndex=0;$profileIndex -lt $plan.profiles.Count;$profileIndex++){$profile=$plan.profiles[$profileIndex];foreach($style in $plan.styles){for($inputIndex=0;$inputIndex -lt $plan.texts.Count;$inputIndex++){foreach($route in @('string','chars')){foreach($trying in @($false,$true)){$format=[Globalization.NumberFormatInfo]::new();$format.NegativeSign=(UnitsText $profile.negative);$format.PositiveSign=(UnitsText $profile.positive);$format.NumberDecimalSeparator=(UnitsText $profile.decimal);$format.NumberGroupSeparator=(UnitsText $profile.group);$format.CurrencySymbol=(UnitsText $profile.currencySymbol);$format.CurrencyDecimalSeparator=(UnitsText $profile.currencyDecimal);$format.CurrencyGroupSeparator=(UnitsText $profile.currencyGroup);$format.NumberNegativePattern=$profile.negativePattern;$provider=[Activator]::CreateInstance($providerType);switch($profile.kind){'custom'{$provider.Result=$format};'wrong'{$provider.Result='wrong'};'throwing'{$provider.Error=[InvalidOperationException]::new('provider failure')};'format-throwing'{$provider.Error=[FormatException]::new('provider format failure')};'overflow-throwing'{$provider.Error=[OverflowException]::new('provider overflow failure')}};$holder=[Array]::CreateInstance($native,1);$holder.SetValue([Convert]::ChangeType(123,$native,[Globalization.CultureInfo]::InvariantCulture),0);$arguments=[object[]]::new(4);$arguments[0]=(UnitsText $plan.texts[$inputIndex]);$arguments[1]=[int]$style;$arguments[2]=$provider;$arguments[3]=$holder;$sameError=$false;try{$value=$delegates["$name/$route/$trying"].DynamicInvoke($arguments);if($trying){$result=[ordered]@{ok=$true;value=[bool]$value}}else{$result=[ordered]@{ok=$true;value=$value.ToString()}}}catch{$result=Failure $_;$exception=$_.Exception;while($exception -is [Reflection.TargetInvocationException] -or $exception -is [Management.Automation.MethodInvocationExcep